    students = [{'study_hours': 5, 'absences': 1, 'hw_rate': 0.6}, {'study_hours': 6, 'absences': 5, 'hw_rate': 0.9},
                {'study_hours': 2, 'absences': 0, 'hw_rate': 1.0}, {'study_hours': 3, 'absences': 4, 'hw_rate': 0.5}]
    out = []
    for s in students:
        n = 'A'
