from fractions import Fraction
NODES = [('P', 10, 10), ('Q', 36, 4), ('R', 0, 25), ('S', 30, 10)]
def answers():
    g = {}
    for name, buy, no in NODES:
        p = Fraction(buy, buy + no)
        g[name] = 1 - p * p - (1 - p) ** 2
    return [', '.join(sorted(g, key=g.get))]
